import Tab from './Tab'

export default {
  title: 'Components/Tab',
  component: Tab,
  subcomponents: {
    'Tab.Group': Tab.Group,
  },
  argTypes: {
    'aria-controls': {
      control: false,
    },
    children: {
      control: false,
    },
    color: {
      table: {
        category: 'Appearance',
        defaultValue: { summary: "'default'" },
      },
    },
    disabled: {
      table: {
        category: 'State',
        defaultValue: { summary: 'false' },
      },
    },
    id: {
      control: false,
    },
    size: {
      table: {
        category: 'Appearance',
        defaultValue: { summary: "'large'" },
      },
    },
    startAdornment: {
      control: { type: 'select' },
      options: ['None', ...Object.keys(Icons)],
      mapping: { None: undefined, ...Icons },
      table: {
        category: 'Content',
        defaultValue: { summary: 'undefined' },
      },
    },
    align: {
      control: { type: 'select' },
      options: [...TAB_ALIGN_VALUES],
      table: {
        category: 'Appearance',
        defaultValue: { summary: "'stretch'" },
      },
    },
  },
  args: {
    align: 'stretch',
    color: 'default',
    disabled: false,
    size: 'large',
  },
}

function Template(args: {
  align?: TabAlign
  color?: TabColor
  defaultTab?: string
  disabled?: boolean
  size?: TabSize
  startAdornment?: typeof Star
}): JSX.Element {
  return (
    <Tab.Group
      align={args.align}
      color={args.color}
      defaultTab={args.defaultTab || 'one'}
      disabled={args.disabled}
      onClick={() => void 0}
      size={args.size}
    >
      <Tab
        onClick={() => void 0}
        startAdornment={args.startAdornment}
        value="one"
      >
        Tab 1
      </Tab>
      <Tab
        onClick={() => void 0}
        startAdornment={args.startAdornment}
        value="two"
      >
        Tab 2
      </Tab>
      <Tab
        onClick={() => void 0}
        startAdornment={args.startAdornment}
        value="three"
      >
        Tab 3
      </Tab>
    </Tab.Group>
  )
}

export const Default = {
  render: Template,
}

